import{_ as t,H as a,f as i,i as s}from"./chunks/framework.BH2BK_3i.js";const f=JSON.parse('{"title":"好诗相伴04｜见众生：众生皆苦亦哲学","description":"","frontmatter":{},"headers":[],"relativePath":"如何读懂一首诗/好诗相伴04｜见众生：众生皆苦亦哲学.md","filePath":"如何读懂一首诗/好诗相伴04｜见众生：众生皆苦亦哲学.md","lastUpdated":1779819710000}'),n={name:"如何读懂一首诗/好诗相伴04｜见众生：众生皆苦亦哲学.md"};function E(r,e,o,g,b,c){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="好诗相伴04-见众生-众生皆苦亦哲学" tabindex="-1">好诗相伴04｜见众生：众生皆苦亦哲学 <a class="header-anchor" href="#好诗相伴04-见众生-众生皆苦亦哲学" aria-label="Permalink to &quot;好诗相伴04｜见众生：众生皆苦亦哲学&quot;">​</a></h1><p>好诗相伴，千金不换，你好，我是天博。</p><p>今天我们的“好诗相伴”，我想给你读的是“见众生”这个话题下的诗。见众生就是读诗词里的人性。我们在这个话题下讲了诗词里的民生疾苦、升迁贬谪，还有女性视角和哲学这四个方面的诗词。</p><p>讲 <a href="https://time.geekbang.org/column/article/398064" target="_blank" rel="noreferrer">民生疾苦</a> 的时候，我们讲的是杜甫对人民的悲悯，主要讲了他的《阁夜》，讲他经历的时候，还顺带提到了他的《望岳》，最后在煮酒论诗里分享了他的《咏怀古迹五首·其一》。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417801/d7b98c7f3d97eb209e506697c6747693.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417801/d7b98c7f3d97eb209e506697c6747693.jpg" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417801/9126bf7fd065aceb45fb08300yy5463d.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417801/9126bf7fd065aceb45fb08300yy5463d.jpg" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417801/f9d7fb66ef6dcb178e545b47706d5e80.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417801/f9d7fb66ef6dcb178e545b47706d5e80.jpg" alt=""></a></p><p>在讲 <a href="https://time.geekbang.org/column/article/398872" target="_blank" rel="noreferrer">升迁贬谪</a> 的时候，我们主要讲的是刘禹锡面对贬谪的耿直，讲了他在玄都观写的两首桃花诗《玄都观桃花》和《再游玄都观》，在讲刘禹锡的经历的时候，还讲了他的《酬乐天扬州初逢席上见赠》，最后在煮酒论诗里我还给你分享了他的《西塞山怀古》。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417801/4065362c3c8ee54a20ec207d0f6fd7b3.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417801/4065362c3c8ee54a20ec207d0f6fd7b3.jpg" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417801/33f8f210bb1f846066f1d6366e1d0eeb.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417801/33f8f210bb1f846066f1d6366e1d0eeb.jpg" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417801/18bef7bf9c767af57270203eaa98c657.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417801/18bef7bf9c767af57270203eaa98c657.jpg" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417801/0931c049a18322def6eaa1bab8771210.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417801/0931c049a18322def6eaa1bab8771210.jpg" alt=""></a></p><p>在讲 <a href="https://time.geekbang.org/column/article/399775" target="_blank" rel="noreferrer">女性视角</a> 的时候，我们讲的是女性视角下独到的细腻，主要讲了李清照少女时期写的《点绛唇·蹴罢秋千》，还讲了同为女性的李冶写的《八至》，最后在煮酒论诗里我和你分享了李清照的另一首词，《减字木兰花·卖花担上》。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417801/6ea398c0d4d3d117e1152f8cd0a92dd4.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417801/6ea398c0d4d3d117e1152f8cd0a92dd4.jpg" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417801/ec52ayyd725c066629de1ffeeaf05650.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417801/ec52ayyd725c066629de1ffeeaf05650.jpg" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417801/f3bfa9d904a3fbebyy9896e2a952d761.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417801/f3bfa9d904a3fbebyy9896e2a952d761.jpg" alt=""></a></p><p>在这个话题的第四讲里，我们讲的是诗人们面对众生理性的一面，也就是 <a href="https://time.geekbang.org/column/article/400615" target="_blank" rel="noreferrer">理趣诗</a>，主要讲了苏轼的《观潮》，顺带讲了朱熹的《观书有感·其二》，最后在煮酒论诗里我们一起分享了苏轼的另一首诗《琴诗》。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417801/7635fe19f50f59d7af69ef2007355aa7.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417801/7635fe19f50f59d7af69ef2007355aa7.jpg" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417801/365f2246d17afe35795c4503f8c7155b.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417801/365f2246d17afe35795c4503f8c7155b.jpg" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417801/f8e778eafa8b1d7836b0faf3cd95984e.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A6%82%E4%BD%95%E8%AF%BB%E6%87%82%E4%B8%80%E9%A6%96%E8%AF%97/images/417801/f8e778eafa8b1d7836b0faf3cd95984e.jpg" alt=""></a></p><p>到这里，我们今天的好诗相伴的第四讲就结束了。如果这里面有你喜欢的诗，欢迎你多听两遍，也欢迎你把这些诗分享给自己的朋友，我们下一讲再见。</p>',21)])])}const p=t(n,[["render",E]]);export{f as __pageData,p as default};
